from urllib.parse import quote
NAME="Corliss Parker"
SCRIPT_EMAIL="corlissparker@corlissparker.org"
PLAYS=[('no-more-rainbows', 'No More Rainbows?', 'c', 'Alice, a retired psychologist and long-time activist, is determined to continue marching for environmental justice and human rights, in spite of a recent serious fall and impaired vision. While celebrating her mother’s seventy-fifth birthday, Lara pleads with Alice to stay home and skip a demonstration she helped organize. ICE agents have arrived in their city and are searching for a family they love. Lara fears her mother will be hurt and might fall again. Alice’s lover, daughter, grand-daughter, and several spirits offer advice and testimony. Alice must decide how she will respond to potential and real threats to herself, her friends, and the democracy she loves.'), ('palindromes', 'Palindromes', 'o', 'Katy, a busy New York City therapist and mother of teens, receives a frantic, middle-of-the-night call from her brother in December, 2001. Matt has gotten an eviction notice, and he is desperate. He has lived in THE TEXAS ARMS, a trailer park in a suburb near Austin, for years. Old anxieties and symptoms linked to an earlier experience of homelessness following his chaotic return from Vietnam, resurface. Matt tells Katy he will move into a cave in the Hill Country. She immediately flies to Austin, sees and feeds Matt, and speaks with their parents and administrators in the Veterans Association and other agencies. After engaging in a scuffle with the manager of Matt’s trailer park, she offers Matt a housing option he may or may not accept.\nPALINDROMES received a staged reading in September, 2025, at the Emerging Artists Theatre’s SPARK Festival in NYC.'), ('saint-james', 'Saint James', 'c', 'Two teens — one a climate change believer and activist, the other a climate change skeptic — spar during a Climate Club meeting in their midwestern high school. Kat is slightly injured and mocked on social media when Matt knocks her poster over. She refuses to return to school. Later, with the help of Abe Brooks, their principal, and Sandy Miller, a retired school psychologist, the teens learn to listen to and empathize with each other. Views about environmental injustice, and evangelical theories and scientific evidence of climate change are explored.\nSAINT JAMES was a first runner-up in the Don McCann Memorial One-Act Playwriting Festival in 2025.'), ('justice-finds-minister-thorne', 'Justice Finds Minister Thorne', 'o', 'In the late twenty-first century, in an unnamed, heavily-polluted ocean, Astraea, the ancient mythological Goddess of Justice, sits in a lifeboat in heavy fog with Sammy, a former boy soldier from Somalia. Mute after being tortured, Sammy communicates with Astraea with gestures. Their lifeboat hits a wave when Arthur Thorne, Minister of Internal and External Affairs and Chief Advisor to the self-proclaimed Emperor of the Western World, thrusts an arm over the side of their boat. Gasping for air and soaking wet, Thorne rudely addresses Sammy. Astraea confronts Thorne about edicts and actions he has taken that have injured and destroyed millions of people. The Furies appear, and Astraea and Thorne spar over how justice will be served.'), ('oceans-inn', 'Ocean’s Inn', 'c', 'Carole and Simon, former lovers now in their late fifties, meet by chance on an Upper West Side Manhattan street undergoing extreme gentrification. They reminisce about the neighborhood they once loved and lost, the overabundance of gaudy, glossy shops and sterile banks, and their lost relationship. They laugh, cry, rehash old wounds, embrace, and reconsider their futures.'), ('under-cover', 'Under Cover', 'o', 'Sophie, both as a ten-year-old and a twenty-two-year-old, stages and describes Duck and Cover, the Civil Defense action propagated and practiced in the United States during the Cold War. Interactions among members of a deeply religious, conservative, military family are described. Conversations between Sophie and her parents and her Roman Catholic teachers about faith, obedience and miracles are staged. Ultimately, twenty-two-year-old Sophie celebrates a fragile independence from past troubled relationships.')]
def head(t,d):
    return f'''<!DOCTYPE html>
<!-- Corliss Parker Website 1.2 -->
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{t}</title><meta name="description" content="{d[:150]}">
<meta name="robots" content="noai, noimageai"><meta name="googlebot" content="noai, noimageai">
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@600&family=Lora:ital@0;1&display=swap" rel="stylesheet">
<link href="css/style.css" rel="stylesheet"></head><body>
<div class="header"><div class="container"><a class="logo" href="index.html">{NAME}</a>
<ul class="nav"><li><a href="index.html">Home</a></li>
<li><a href="plays.html">Plays</a><ul>{"".join(f'<li><a href="{s}.html">{n}</a></li>' for s,n,_,_ in PLAYS)}</ul></li><li><a href="#contact">Contact</a></li></ul></div></div>'''
FOOT=f'''<div class="footer" id="contact"><div class="container"><div class="footer-grid">
<div><h2>Contact Me</h2><p>Email: <a href="mailto:corlissparker@corlissparker.org">corlissparker@corlissparker.org</a></p></div>
<div><h2>Notice</h2><p>All writing on this site is the original work of {NAME}. It may not be copied, republished, or used to train or feed AI or machine-learning systems.</p></div></div>
<div class="tiny">&copy; 2026 {NAME}. All rights reserved. No AI scraping or training.</div></div></div></body></html>'''
def banner(t,c): return f'<div class="page-header"><div class="container"><h1>{t}</h1><p class="breadcrumb">{c}</p></div></div>'
def w(f,s): open(f,"w").write(s)
N=len(PLAYS)
w("index.html",head(f"{NAME} | Playwright","Playwright. Read her plays online.")+f'''
<div class="container"><div class="hero"><img class="portrait" src="images/portrait.jpg" alt="Portrait of {NAME}" width="480" height="622">
<div><h1>{NAME}</h1><p class="role">Playwright &middot; Psychoanalyst</p><div class="quotes"><blockquote class="qcard q1"><p>You’ve gotta dance like there’s nobody watching.</p><cite>W. W. Purkey</cite></blockquote><blockquote class="qcard q2"><p>Hope is the thing with feathers that perches in the soul.</p><cite>Emily Dickinson</cite></blockquote></div></div></div>
<h2>About</h2>
<p>Corliss Parker is a playwright and short story writer whose work examines the human condition in modern times. She explores how people experience joy, love, loss, fear and confusion in the contexts of current planetary upheavals, human migrations, emerging advanced technologies, extreme climate events, political chaos and wars. While striving to represent the humor, pathos, and tragedy in the human experiment, she often reminds herself of Samuel Beckett’s words: “Try again. Fail again. Fail better.”</p>
<p>Corliss has been writing plays and short stories for three years. She worked many decades as a clinical psychologist, a therapist, and a professor of psychology. It was an awesome, rewarding, challenging profession. She is not an award-winning playwright, though she imagines what that might feel like. She has had several staged readings in New York City and was a finalist in the Don McCann Memorial One-Act Playwriting Contest in 2025. Writing is the gift that contains and eases Corliss’s sadness and despair over human beings’ terrifying capacity to hurt one another. Creating and documenting truths gives her hope in the human capacity to love and repair and care for one another.</p>
<div class="band"><h2>{N} plays to read</h2><p>Explore the full collection.</p><a class="btn" href="plays.html">Browse the plays</a></div></div>'''+FOOT)
cards="".join(f'<div class="card"><a class="cover {im}" href="{s}.html" aria-label="Read {n}">{n}<small>Click to read</small></a><div><p>{d[:170].rsplit(" ",1)[0]}…</p><a class="btn" href="{s}.html">Read this play</a></div></div>' for s,n,im,d in PLAYS)
w("plays.html",head(f"Plays | {NAME}","Read the plays of "+NAME)+banner("Plays",'<a href="index.html">Home</a> / Plays')+f'<div class="content"><div class="container"><div class="grid">{cards}</div></div></div>'+FOOT)
for i,(s,n,im,d) in enumerate(PLAYS,1):
    pg="".join(f'<li{" class=active" if k==i else ""}><a href="{PLAYS[k-1][0]}.html" title="{PLAYS[k-1][1]}">{k}</a></li>' for k in range(1,N+1))
    pv=f'<li><a href="{PLAYS[i-2][0]}.html">Previous</a></li>' if i>1 else ""
    nx=f'<li><a href="{PLAYS[i][0]}.html">Next</a></li>' if i<N else '<li><a href="plays.html">All plays</a></li>'
    w(f"{s}.html",head(f"{n} | {NAME}",d)+banner(n,f'<a href="index.html">Home</a> / <a href="plays.html">Plays</a> / Play {i} of {N}')+
    f'<div class="content"><div class="container reading"><p class="notice">&copy; 2026 {NAME}. All rights reserved.</p><p class="lead">{d.replace(chr(10),"</p><p class=\"lead\">")}</p><div class="access"><p>To access this script, contact me at:</p><a class="btn" href="mailto:{SCRIPT_EMAIL}?subject=Script%20request%3A%20{quote(n)}">{SCRIPT_EMAIL}</a></div><ul class="pagination">{pv}{pg}{nx}</ul></div></div>'+FOOT)
